from collections import Counter
from pathlib import Path
from statistics import mean, median, stdev

import matplotlib.pyplot as plt


# SENTINEL_MISSING = -1000.0


# def _clean_values(values):
# 	"""Drop sentinel values used for missing probing maxima."""
# 	return [v for v in values if v != SENTINEL_MISSING]


def plot_max_probing_histograms(max_probing_dict, bins=40):
	nts_order = ["A", "C", "G", "U"]
	colors = {
		"A": "#d95f02",
		"C": "#1b9e77",
		"G": "#7570b3",
		"U": "#e7298a",
	}

	fig, axes = plt.subplots(2, 2, figsize=(12, 8), sharey=True)
	axes = axes.flatten()

	for ax, nt in zip(axes, nts_order):
		values = [v for v in max_probing_dict.get(nt, [])]
		if not values:
			ax.text(0.5, 0.5, f"No data for {nt}", ha="center", va="center")
			ax.set_title(f"{nt} (n=0)")
			continue

		ax.hist(values, bins=bins, color=colors[nt], alpha=0.8, edgecolor="black")
		ax.set_title(f"{nt} max probing values (n={len(values)})")
		ax.set_xlabel("Max probing value")
		ax.set_ylabel("Count")
		ax.grid(alpha=0.2)

	fig.suptitle("Distribution of max probing value by nucleotide", fontsize=14)
	fig.tight_layout()
	return fig


def plot_max_nt_frequency(max_nt_list):
	nts_order = ["A", "C", "G", "U"]
	counts = Counter(max_nt_list)
	freqs = [counts.get(nt, 0) for nt in nts_order]

	fig, ax = plt.subplots(figsize=(7, 5))
	bars = ax.bar(nts_order, freqs, color=["#d95f02", "#1b9e77", "#7570b3", "#e7298a"])

	ax.set_title("Frequency of nucleotide with max probing")
	ax.set_xlabel("Nucleotide")
	ax.set_ylabel("Count")
	ax.grid(axis="y", alpha=0.25)

	for bar, count in zip(bars, freqs):
		ax.text(
			bar.get_x() + bar.get_width() / 2,
			bar.get_height(),
			str(count),
			ha="center",
			va="bottom",
		)

	fig.tight_layout()
	return fig


def print_max_probing_summary(max_probing_dict):
	print("\nSummary stats for max_probing_by_nt")
	print("nt\tn\tmean\tstdev\tmedian")
	all_values = []

	for nt in ["A", "C", "G", "U"]:
		values = max_probing_dict.get(nt, [])
		all_values.extend(values)
		if not values:
			print(f"{nt}\t0\tNA\tNA\tNA")
			continue

		nt_mean = mean(values)
		nt_median = median(values)
		nt_stdev = stdev(values) if len(values) > 1 else 0.0
		print(f"{nt}\t{len(values)}\t{nt_mean:.4f}\t{nt_stdev:.4f}\t{nt_median:.4f}")

	if not all_values:
		print("OVERALL\t0\tNA\tNA\tNA")
		return

	overall_mean = mean(all_values)
	overall_median = median(all_values)
	overall_stdev = stdev(all_values) if len(all_values) > 1 else 0.0
	print(f"OVERALL\t{len(all_values)}\t{overall_mean:.4f}\t{overall_stdev:.4f}\t{overall_median:.4f}")


def save_figures(output_dir=None, show=False):
	output_path = Path(output_dir) if output_dir else Path(__file__).resolve().parent
	output_path.mkdir(parents=True, exist_ok=True)

	print_max_probing_summary(max_probing_by_nt)

	probing_fig = plot_max_probing_histograms(max_probing_by_nt, bins=40)
	probing_file = output_path / "max_probing_by_nt_histograms.png"
	probing_fig.savefig(probing_file, dpi=300, bbox_inches="tight")

	max_nt_fig = plot_max_nt_frequency(max_nts)
	max_nt_file = output_path / "max_nt_frequency_histogram.png"
	max_nt_fig.savefig(max_nt_file, dpi=300, bbox_inches="tight")

	if show:
		plt.show()
	else:
		plt.close(probing_fig)
		plt.close(max_nt_fig)

	print(f"Saved: {probing_file}")
	print(f"Saved: {max_nt_file}")


if __name__ == "__main__":
	save_figures(show=False)
